    row = matrix.get(cat, {})
    for pf in CANONICAL_PLATFORMS:
        cell = row.get(pf, {})
        if isinstance(cell, dict) and cell.get("state") == "未収集":
            unresolved_cells.append((cat, pf))
if unresolved_cells:
    print(f"  未収集セル数: {len(unresolved_cells)}")
    for c,p in unresolved_cells:
        print(f"  - matrix[{c}][{p}]")
    # 追跡チェック
    next_q = hearing.get("next_question")
    loop_complete = hearing.get("complete", False)
    print(f"  hearing_progress.complete={loop_complete}, next_question={next_q!r}")
else:
    print("  未収集セルなし (0件)")

print()
print("=== AXIS-B: 対象外理由の妥当性 ===")
excluded_cells_total = 0
placeholder_cells = []
for cat in cats:
    row = matrix.get(cat, {})
    for pf in CANONICAL_PLATFORMS:
        cell = row.get(pf, {})
        if isinstance(cell, dict) and cell.get("state") == "対象外":
            excluded_cells_total += 1
            reason = cell.get("reason", "")
            reason_stripped = reason.strip() if reason else ""
            is_placeholder = (
                reason_stripped in PLACEHOLDER_PATTERNS or
                reason_stripped.lower() in {"n/a","-","tbd"} or
                len(reason_stripped) == 0
            )
            # Also check for same-word repetition (同語反復): reason contains only "対象外"
            if reason_stripped == "対象外":
                is_placeholder = True
            if is_placeholder:
                placeholder_cells.append((cat, pf, reason))
print(f"  対象外セル総数: {excluded_cells_total}")
if placeholder_cells:
    print(f"  理由要改善 (placeholder): {len(placeholder_cells)}件")
    for c,p,r in placeholder_cells:
        print(f"  - matrix[{c}][{p}]: reason={r!r}")
else:
    print("  理由要改善 (placeholder) なし")
    # Print sample reasons for verification
    sample = []
    for cat in cats[:2]:
        row = matrix.get(cat, {})
        for pf in list(CANONICAL_PLATFORMS)[1:3]:
            cell = row.get(pf, {})
            if isinstance(cell, dict) and cell.get("state") == "対象外":
                sample.append((cat, pf, cell.get("reason","")))
    for c,p,r in sample:
        print(f"  (sample) matrix[{c}][{p}]: reason={r!r}")

print()
print("=== AXIS-C: 確定 qa_ref トレーサビリティ ===")
confirmed_cells = []
dangling_cells = []
for cat in cats:
    row = matrix.get(cat, {})
    for pf in CANONICAL_PLATFORMS:
        cell = row.get(pf, {})
        if isinstance(cell, dict) and cell.get("state") == "確定":
            qa_ref = cell.get("qa_ref","")
            confirmed_cells.append((cat, pf, qa_ref))
            if qa_ref not in all_ref_ids:
                dangling_cells.append((cat, pf, qa_ref, "dangling: qa_log/approval_log に不在"))
            else:
                # Check if qa_log entry actually covers this category×platform
                if qa_ref in qa_log:
                    entry = qa_log[qa_ref]
                    q_text = entry.get("question","")
                    a_text = entry.get("answer","")
                    # Minimal check: does it mention the category or platform?
                    # For approval_log entries, check note
                elif qa_ref in approval_log:
                    entry = approval_log[qa_ref]
print(f"  確定セル総数: {len(confirmed_cells)}")
if dangling_cells:
    print(f"  qa_ref 要確認 (dangling/不在): {len(dangling_cells)}")
    for c,p,r,note in dangling_cells:
        print(f"  - matrix[{c}][{p}]: qa_ref={r!r} -> {note}")
else:
    print("  dangling qa_ref なし")
    for c,p,r in confirmed_cells:
        ref_type = "qa_log" if r in qa_log else "approval_log"
        print(f"  - matrix[{c}][{p}]: qa_ref={r!r} -> {ref_type} に存在")

